import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // Main button mesh
  const buttonMesh = createButtonMesh();
  root.add(buttonMesh);
  disposables.push(buttonMesh);

  // Contact shadow plane
  const shadowMesh = createShadowMesh();
  shadowMesh.position.z = -0.08;
  root.add(shadowMesh);
  disposables.push(shadowMesh);

  // Text rendering via fontAtlas
  const textGroup = new THREE.Group();

  // Main CTA label "BEGIN COMMISSION"
  if (ctx && ctx.fontAtlas) {
    const ctaTextMesh = ctx.fontAtlas({
      text: 'BEGIN COMMISSION',
      fontSize: 20,
      fontWeight: 700,
      fontFamily: 'JetBrains Mono',
      color: '#e8ecf2',
      atlasIndex: 0,
      atlasRegion: [0, 0, 512, 320]
    });
    if (ctaTextMesh) {
      ctaTextMesh.position.z = 0.01;
      textGroup.add(ctaTextMesh);
      disposables.push(ctaTextMesh);
    }

    // Caption "NO DEPOSIT REQUIRED"
    const captionTextMesh = ctx.fontAtlas({
      text: 'NO DEPOSIT REQUIRED',
      fontSize: 9,
      fontWeight: 400,
      fontFamily: 'JetBrains Mono',
      color: '#e8ecf2',
      atlasIndex: 0,
      atlasRegion: [0, 0, 512, 320]
    });
    if (captionTextMesh) {
      captionTextMesh.position.y = -0.26;
      captionTextMesh.position.z = 0.01;
      textGroup.add(captionTextMesh);
      disposables.push(captionTextMesh);
    }
  }

  root.add(textGroup);

  // Mount animation: weighted-settle scale from 1.04 to 1.0
  const mountTl = gsap.timeline();
  mountTl.from(root.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)'
  });
  timelines.push(mountTl);

  // Event handlers for interactions
  let hoverTl, pressTl;

  root.userData.handlers = {
    pointerenter() {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(buttonMesh.position, {
        z: 0.06,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);
      timelines.push(hoverTl);
    },
    pointerleave() {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(buttonMesh.position, {
        z: 0,
        duration: 0.18,
        ease: 'power2.out'
      }, 0);
      timelines.push(hoverTl);
    },
    pointerdown() {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      }, 0);
      pressTl.to(shadowMesh.material, {
        opacity: 0.5,
        duration: 0.12
      }, 0);
      timelines.push(pressTl);
    },
    pointerup() {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out'
      }, 0);
      pressTl.to(shadowMesh.material, {
        opacity: 0.35,
        duration: 0.12
      }, 0);
      timelines.push(pressTl);
    }
  };

  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach(m => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}

function createButtonMesh() {
  const w = 2.6;
  const h = 0.68;
  const geometry = new THREE.PlaneGeometry(w, h, 32, 32);

  // Create gradient using THREE canvas texture
  // Top (#ff4450) -> Mid (#ff2a38 at 55%) -> Bottom (#c1121f)
  const canvas = new OffscreenCanvas(512, 320);
  const ctx = canvas.getContext('2d');

  const grad = ctx.createLinearGradient(0, 0, 0, 320);
  grad.addColorStop(0, '#ff4450');
  grad.addColorStop(0.55, '#ff2a38');
  grad.addColorStop(1, '#c1121f');

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 512, 320);

  // Hard seam line at 50%
  ctx.strokeStyle = '#ff2a38';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, 160);
  ctx.lineTo(512, 160);
  ctx.stroke();

  // Convert canvas to bitmap and then texture
  canvas.convertToBlob().then(blob => {
    const bmp = createImageBitmap(blob).then(bitmap => {
      const tex = new THREE.CanvasTexture(bitmap);
      material.map = tex;
      material.needsUpdate = true;
    });
  }).catch(() => {
    // Fallback: use simple color if canvas fails
  });

  const material = new THREE.MeshStandardMaterial({
    color: 0xff2a38,
    metalness: 0.35,
    roughness: 0.5,
    clearcoat: 0.22,
    emissive: 0xff2a38,
    emissiveIntensity: 1.6,
    side: THREE.FrontSide
  });

  return new THREE.Mesh(geometry, material);
}

function createShadowMesh() {
  const w = 2.6 * 0.95;
  const h = 0.68 * 0.95;
  const geometry = new THREE.PlaneGeometry(w, h);
  const material = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35
  });
  return new THREE.Mesh(geometry, material);
}
